use vstd::prelude::*;

verus! {

    // For each position i, returns a boolean vector `res` of the same length
    // such that res[i] == (a[i] < b[i]).
    // We require the two inputs have the same length, and we ensure the
    // output length matches and the pointwise comparison property.
    fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool>
      requires
        a.len() == b.len(),
      ensures
        |res: Vec<bool>| 
            res.len() == a.len()
            && forall(|i: usize| i < a.len() ==> res[i] <==> a[i] < b[i]),
    {
        let mut res: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        // Loop over all indices 0..a.len()
        while i < a.len()
          invariant
            // 0 <= i <= a.len()
            i <= a.len(),
            // we've built exactly `i` results so far
            res.len() == i,
            // for all j < i, res[j] == (a[j] < b[j])
            forall(|j: usize| j < i ==> res[j] <==> a[j] < b[j]),
          decreases
            a.len() - i
        {
            // compute the boolean for this index
            let v: bool = a[i] < b[i];
            res.push(v);
            i += 1;
        }
        res
    }

} // end verus! 

